'use strict';

// MODULES //

var tape = require( 'tape' );
var hammingDistanceCodePoints = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof hammingDistanceCodePoints, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a string as its first argument', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			hammingDistanceCodePoints( value, 'foo' );
		};
	}
});

tape( 'the function throws an error if not provided a string as its second argument', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			hammingDistanceCodePoints( 'foo', value );
		};
	}
});

tape( 'the function returns -1 as a sentinel value if provided strings with an unequal number of Unicode code points', function test( t ) {
	t.strictEqual( hammingDistanceCodePoints( 'length', 'differs' ), -1, 'returns expected value' );
	t.strictEqual( hammingDistanceCodePoints( 'a', 'ab' ), -1, 'returns expected value' );
	t.strictEqual( hammingDistanceCodePoints( '👋', 'ab' ), -1, 'returns expected value' );
	t.strictEqual( hammingDistanceCodePoints( 'abc', '👋' ), -1, 'returns expected value' );
	t.end();
});

tape( 'the function calculates the Hamming distance between two equal-length strings (ASCII)', function test( t ) {
	var expected;
	var values;
	var i;

	values = [
		[ '1638452297', '4444884442' ], // 10
		[ '', '' ],                     // 0
		[ 'a', 'a' ],                   // 0
		[ 'a', 'b' ],                   // 1
		[ 'xy', 'xy' ],                 // 0
		[ 'xx', 'xy' ],                 // 1
		[ 'frog', 'blog' ],             // 2
		[ 'fly', 'ant' ],               // 3
		[ 'hello', 'hallo' ],           // 1
		[ 'congratulations', 'conmgeautlatins' ] // 9
	];

	expected = [ 10, 0, 0, 1, 0, 1, 2, 3, 1, 9 ];

	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( hammingDistanceCodePoints( values[i][0], values[i][1] ), expected[i], 'returns expected value' );
	}
	t.end();
});

tape( 'the function calculates the Hamming distance between two equal-length strings (emoji / surrogate pairs)', function test( t ) {
	var expected;
	var values;
	var i;

	// Each emoji is a single Unicode code point encoded as a UTF-16 surrogate pair.
	values = [
		[ '👋', '👋' ],           // same emoji: 0
		[ '👋', '🌍' ],           // different emoji: 1
		[ '👋🌍', '🌍👋' ],       // swapped pair: 2
		[ '👋🌍🎉', '🌟💫✨' ],   // all different: 3
		[ 'a👋', 'a🌍' ],         // ASCII + emoji, first matches: 1
		[ 'a👋b', 'c🌍d' ],       // mixed: all three differ: 3
		[ 'hello👋', 'hallo🌍' ]  // ASCII substring differs: 2
	];

	expected = [ 0, 1, 2, 3, 1, 3, 2 ];

	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( hammingDistanceCodePoints( values[i][0], values[i][1] ), expected[i], 'returns expected value for pair: ' + JSON.stringify(values[i]) );
	}
	t.end();
});

tape( 'the function treats a surrogate pair as a single code point when comparing lengths', function test( t ) {
	// '👋' has UTF-16 length 2, but is 1 Unicode code point.
	// 'ab' has UTF-16 length 2, and is 2 Unicode code points.
	// Therefore their code point counts differ and the result should be -1.
	t.strictEqual( hammingDistanceCodePoints( '👋', 'ab' ), -1, 'returns expected value' );
	t.strictEqual( hammingDistanceCodePoints( 'ab', '👋' ), -1, 'returns expected value' );

	// 'a👋' has 2 code points; 'bc' has 2 code points — equal length, so compare:
	t.strictEqual( hammingDistanceCodePoints( 'a👋', 'bc' ), 2, 'returns expected value' );
	t.end();
});
